 $('nav').innerHTML=groups.map(([label,keys])=>{
   const links=keys.filter(k=>visiblePages().includes(k)).map(k=>`<a href="#/${k}" data-page="${k}"><span class="nav-icon" aria-hidden="true">${uiIcon(k)}</span><span>${esc(paths[k][0])}</span></a>`).join('');
   return links?`<div class="nav-group"><p class="nav-heading">${label}</p>${links}</div>`:'';
 }).join('');
